def naive_poly(x):
    r = 1 + 5 * x + (-6) * (x*x) + 1 * (x*x*x) + (-8) * (x*x*x*x) + (-8) * (x*x*x*x*x) + 6 * (x*x*x*x*x*x) + (-6) * (x*x*x*x*x*x*x)
    return r

def dot_product(a0, a1, a2, a3, a4, a5, a6, a7, b0, b1, b2, b3, b4, b5, b6, b7):
    s = a0 * b0 + a1 * b1 + a2 * b2 + a3 * b3 + a4 * b4 + a5 * b5 + a6 * b6 + a7 * b7
    return s
